// passage of the site's full translation first, then one question on it, with
// four choices (as in the Engels Ludwig Feuerbach course). Korean passages are
// verbatim from the document marx-wage-labour-and-capital (scripts/check-course-source-excerpts.js
// checks them and their anchors). The English passages are translated here from the German
// text the document carries.
// A passage may skip text with ' … '.
// Rewritten 2026-10-31 from the earlier quiz course: chapter ids stay (wage-labour-chNN) so chapter links keep working. Every question is new, so the lessons take new ids
// (wage-labour-chNN-reading) and old quiz answer history is not counted for them.

function t(ko, en) {
    return { ko, en };
}

const DOC = '/commulingo/docs/marx-wage-labour-and-capital';
const FROM_ORIGINAL = ' (our translation from the German)';
const TITLE_KO = '『임금노동과 자본』';
const TITLE_EN = 'Wage Labour and Capital';

const LABELS = {
    'introduction': t(`${TITLE_KO} 엥겔스의 서문(1891)`, `${TITLE_EN}, Engels's introduction of 1891` + FROM_ORIGINAL),
    'preliminary': t(`${TITLE_KO} 머리말`, `${TITLE_EN}, preliminary remarks` + FROM_ORIGINAL),
    'section-1': t(`${TITLE_KO} 1절`, `${TITLE_EN}, section 1` + FROM_ORIGINAL),
    'section-2': t(`${TITLE_KO} 2절`, `${TITLE_EN}, section 2` + FROM_ORIGINAL),
    'section-3': t(`${TITLE_KO} 3절`, `${TITLE_EN}, section 3` + FROM_ORIGINAL),
    'section-4': t(`${TITLE_KO} 4절`, `${TITLE_EN}, section 4` + FROM_ORIGINAL),
    'section-5': t(`${TITLE_KO} 5절`, `${TITLE_EN}, section 5` + FROM_ORIGINAL),
    'section-6': t(`${TITLE_KO} 6절`, `${TITLE_EN}, section 6` + FROM_ORIGINAL),
    'section-7': t(`${TITLE_KO} 7절`, `${TITLE_EN}, section 7` + FROM_ORIGINAL),
    'section-8': t(`${TITLE_KO} 8절`, `${TITLE_EN}, section 8` + FROM_ORIGINAL),
};

function passage(anchor, contextKo, contextEn, quoteKo, quoteEn) {
    return {
        context: t(contextKo, contextEn),
        source: { href: `${DOC}#${anchor}`, label: LABELS[anchor], quote: t(quoteKo, quoteEn) },
    };
}

// Choices and their feedback are authored correct answer first, which is how
// they are stored (answer 0); the player shuffles them for display.
function q(where, koPrompt, enPrompt, koChoices, enChoices, koExplanation, enExplanation, koFeedback, enFeedback) {
    return {
        type: 'multiple_choice',
        points: 0,
        context: where.context,
        prompt: t(koPrompt, enPrompt),
        choices: { ko: koChoices, en: enChoices },
        answer: 0,
        explanation: t(koExplanation, enExplanation),
        choiceFeedback: { ko: koFeedback, en: enFeedback },
        source: where.source,
    };
}

function chapter(ch, anchor, titleKo, titleEn, summaryKo, summaryEn, questions) {
    const id = `wage-labour-ch${String(ch).padStart(2, '0')}`;
    return {
        id,
        volumeNumber: -2,
        chapterNumber: ch,
        title: t(titleKo, titleEn),
        sourceUrl: `${DOC}#${anchor}`,
        summary: t(summaryKo, summaryEn),
        lessons: [{
            id: `${id}-reading`,
            level: 'basic',
            title: t(titleKo, titleEn),
            questions: questions.map((item, index) => ({ ...item, id: `q${index + 1}`, points: 2 })),
        }],
    };
}

